  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Horizontal bar chart of match attendance by stadium.",
  "data": {
    "url": "data.csv",
    "format": {
      "type": "csv"
    }
  },
  "transform": [
    {
      "window": [
        {
          "op": "rank",
          "as": "rank"
